use std::process::ExitCode;

use wgpu::util::DeviceExt;

const MAX_BINS: u32 = 256;
const WORKGROUP_SIZE: u32 = 256;
const MAX_WORKGROUPS: u32 = 4096;

const SHADER: &str = r#"
struct Params {
    count: u32,
    seed: u32,
    bins: u32,
    _pad: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> hist: array<atomic<u32>, 256>;

var<workgroup> local_hist: array<atomic<u32>, 256>;

fn value_at(i: u32) -> u32 {
    let a = ((i % 40000u) * 1597u + params.seed + 51749u) % 40000u;
    let b = (a * a + a * 37u + 11u) % 40009u;
    let c = (b * 613u + 7919u) % 40009u;
    let d = (c + (i / 40000u) * 7919u) % 40009u;
    return d % 1000u;
}

@compute @workgroup_size(256)
fn main(
    @builtin(local_invocation_index) lid: u32,
    @builtin(global_invocation_id) gid: vec3<u32>,
    @builtin(num_workgroups) nwg: vec3<u32>,
) {
    atomicStore(&local_hist[lid], 0u);
    workgroupBarrier();

    let stride = nwg.x * 256u;
    for (var i = gid.x; i < params.count; i += stride) {
        let v = value_at(i);
        atomicAdd(&local_hist[v * params.bins / 1000u], 1u);
    }
    workgroupBarrier();

    if (lid < params.bins) {
        let n = atomicLoad(&local_hist[lid]);
        if (n != 0u) {
            atomicAdd(&hist[lid], n);
        }
    }
}
"#;

fn parse_input(path: &str) -> Result<(u32, u32, u32), String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let fields: Vec<&str> = text.split_whitespace().collect();
    if fields.len() != 3 {
        return Err(format!("expected 3 numbers in {path}, found {}", fields.len()));
    }
    let parse = |s: &str, name: &str, max: u32| -> Result<u32, String> {
        let v: u32 = s.parse().map_err(|_| format!("invalid {name}: {s:?}"))?;
        if v > max {
            return Err(format!("{name} out of range: {v}"));
        }
        Ok(v)
    };
    let count = parse(fields[0], "count", 4_000_000)?;
    let seed = parse(fields[1], "seed", 9999)?;
    let bins = parse(fields[2], "bins", MAX_BINS)?;
    if bins == 0 {
        return Err("bins must be at least 1".into());
    }
    Ok((count, seed, bins))
}

async fn run_gpu(count: u32, seed: u32, bins: u32) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::default());
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            ..Default::default()
        })
        .await
        .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .map_err(|e| format!("cannot open GPU device: {e}"))?;

    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("histogram"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });

    let params = [count, seed, bins, 0u32];
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let hist_size = u64::from(MAX_BINS) * 4;
    let hist_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("hist"),
        contents: bytemuck::cast_slice(&[0u32; MAX_BINS as usize]),
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: hist_size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("histogram"),
        layout: None,
        module: &shader,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("histogram"),
        layout: &pipeline.get_bind_group_layout(0),
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: params_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: hist_buf.as_entire_binding(),
            },
        ],
    });

    let workgroups = count.div_ceil(WORKGROUP_SIZE).clamp(1, MAX_WORKGROUPS);
    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(workgroups, 1, 1);
    }
    encoder.copy_buffer_to_buffer(&hist_buf, 0, &readback, 0, hist_size);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::Wait)
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("map callback dropped: {e}"))?
        .map_err(|e| format!("cannot map readback buffer: {e}"))?;
    let counts: Vec<u32> = bytemuck::cast_slice(&slice.get_mapped_range()).to_vec();
    readback.unmap();
    Ok(counts[..bins as usize].to_vec())
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu-histogram <input-file>");
        return ExitCode::from(2);
    };
    let (count, seed, bins) = match parse_input(&path) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::from(2);
        }
    };
    let counts = match pollster::block_on(run_gpu(count, seed, bins)) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::FAILURE;
        }
    };

    let mut out = String::new();
    for (i, n) in counts.iter().enumerate() {
        out.push_str(&format!("BIN {i} {n}\n"));
    }
    out.push_str(&format!("TOTAL {count}\n"));
    print!("{out}");
    ExitCode::SUCCESS
}
EOF
